  'entities.zones.palmreach.name': 'パームリーチ',
  'entities.zones.palmreach.welcome':
    '暖かい砂浜、騒がしい鳥の声、そして地平線を呑み込むジャングル。ドリフトヘイヴンは浜辺に火を焚いて待っている。',
  'entities.zones.palmreach.pois.0.label': 'ドリフトヘイヴン',
