  'entities.zones.evergarden.name': 'エバーガーデン',
  'entities.zones.evergarden.welcome':
    '生け垣は今も刈り込まれているのに、庭師の姿は百年も見られていない。迷路には気をつけろ。迷路もお前を見ている。',
  'entities.zones.evergarden.pois.0.label': 'ヘッジウィック',
