  'entities.zones.galecrest.name': 'ゲイルクレスト',
  'entities.zones.galecrest.welcome':
    'ここでは風が一度も止んだことがなく、オールドビーコンの火も一度も消えたことがない。ウィックハーバーの願いはただひとつ、宿の扉をきちんと閉めてくれることだ。',
  'entities.zones.galecrest.pois.0.label': 'ウィックハーバー',
