  'guide.abilityHook.lesser_heal':
    '立ち止まる余裕があるときに味方の体力を満タンに戻す、安定した詠唱です。',
  'guide.abilityHook.life_tap': 'マナが尽きたとき、自分の体力を一部マナに変換します。',
