  'guide.chooser.intro':
    '好みの遊び方で絞り込みましょう。どのクラスも十分に通用するので、これは候補を絞るだけで、順位をつけるものではありません。',
  'guide.chooser.none': 'すべての条件に合うクラスはありません。一つ解除するともっと表示されます。',
