    '強力な近接を持つ巨大なジャガーノートで、純粋な力を求めて召喚します。',
  'guide.petHook.gloomshade': '頑丈なタンク役のデーモン。挑発し、深淵の鎖で逃げる通常の敵を間合いへ引き戻します。ボスは引き寄せに抵抗します。',
